import pandas as pd
df=pd.read_csv('transactions.csv')
df['InvoiceDate']=pd.to_datetime(df['InvoiceDate'])
df['rev']=df.Quantity*df.Price
non=['POST','C2','D','M']
prof=df[~df.StockCode.isin(non)].copy()
for d in (df,prof):
    d['d']=d.InvoiceDate.dt.date
def key(d):
    return (d.month,d.day)
def sl(d,y,cut=None):
    x=d[(d.InvoiceDate>=str(y)+'-10-01')&(d.InvoiceDate<str(y+1)+'-01-01')]
    if cut is not None:
        x=x[x.InvoiceDate<=str(y)+cut]
    return x
target=76018.80
outs=[]
for srcname,src in [('prof',prof),('all',df)]:
    a=sl(src,2010)
    b=sl(src,2011)
    com={key(d) for d in set(a.d)}&{key(d) for d in set(b.d)}
    for a_cut,b_cut in [(None,None),('-12-09',None),(None,'-12-09')]:
        a2=sl(src,2010,a_cut)
        b2=sl(src,2011,b_cut)
        for cmode in ['lfl','full']:
            bs = b2[b2.d.map(key).isin(com)] if cmode=='lfl' else b2
            cset=set(bs.CustomerID.dropna())
            for pmode in ['lfl','full']:
                a3 = a2[a2.d.map(key).isin(com)] if pmode=='lfl' else a2
                for q in ['all','pos']:
                    sa=a3[a3.CustomerID.notna()]
                    if q=='pos':
                        sa=sa[sa.Quantity>0]
                    keep=sa.CustomerID.isin(cset)==False
                    v=round(sa[keep].rev.sum(),2)
                    outs.append((abs(v-target),srcname,str(a_cut),str(b_cut),cmode,pmode,q,v))
for r in sorted(outs)[:8]:
    print(r)
